uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float animationProgress; // min: 0.0, max: 1.0, default: 1.0, 애니메이션 진행도
uniform float bloomIntensity;    // min: 0.0, max: 3.0, default: 1.7, 블룸 강도
uniform float baseCircleSize;    // min: 0.1, max: 1.0, default: 0.5, 기본 원 크기
uniform vec3 primaryColor;       // min: [0.0, 0.0, 0.0], max: [1.0, 1.0, 1.0], default: [0.2, 0.3, 0.9], 주요 컬러 (청록)
uniform vec3 secondaryColor;     // min: [0.0, 0.0, 0.0], max: [1.0, 1.0, 1.0], default: [1.0, 0.4, 0.8], 보조 컬러 (보라)
uniform vec3 accentColor;        // min: [0.0, 0.0, 0.0], max: [1.0, 1.0, 1.0], default: [0.4, 0.9, 0.6], 강조 컬러 (연두)
uniform float overlayAlpha;      // min: 0.0, max: 1.0, default: 0.5, 전체 오버레이 알파값
uniform float circleOpacity;     // min: 0.0, max: 1.0, default: 0.5, 원형 패턴 투명도
uniform float softness;          // min: 0.01, max: 0.3, default: 0.2, 원 가장자리 부드러움
uniform float moveSpeed;         // min: 1.0, max: 50.0, default: 10.0, 원들의 움직임 속도
uniform float sizeVariation;     // min: 0.0, max: 0.8, default: 0.4, 크기 변화 정도
uniform float uAlpha;            // min: 0.0, max: 1.0, default: 1.0, 최종 출력 알파
float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec3 rand3(vec2 p) {
    return vec3(
        hash21(p + vec2(0.0, 0.0)),
        hash21(p + vec2(17.0, 31.0)),
        hash21(p + vec2(43.0, 97.0))
    );
}

vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

    vec2 p = -1.0 + 2.0 * uv;
    p.x *= iResolution.x / iResolution.y;

    vec3 color = vec3(0.0);
    float totalAlpha = 0.0;

    float t = iTime * max(moveSpeed, 0.0001);

    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float pha = sin(fi * 546.13 + 1.0) * 0.5 + 0.5;
        float siz = pow(sin(fi * 651.74 + 5.0) * 0.5 + 0.8, 4.0);
        float pox = sin(fi * 321.55 + 4.1) * (iResolution.x / iResolution.y);

        float rad = (1.0 + 0.5 * siz + sin(t / 6.0 + pha * 500.0 + siz) / 20.0) 
                   * mix(0.9, 1.1, clamp(baseCircleSize, 0.0, 1.0));

        vec2 pos = vec2(
            pox + sin(t / 10.0 + pha + siz),
            -1.0 - rad + (2.33 + 2.0 * rad) * mod(pha + 0.1 * (t / 5.0) * (0.2 + 0.877 * siz), 1.0)
        );

        float dis = length(p - pos);

        // -----------------------------
        // 3가지 색상을 인덱스에 따라 믹스
        // -----------------------------
        float colorPhase = fract(fi * 0.333);
        vec3 col;
        if (colorPhase < 0.333) {
            col = mix(primaryColor, secondaryColor, colorPhase * 3.0);
        } else if (colorPhase < 0.666) {
            col = mix(secondaryColor, accentColor, (colorPhase - 0.333) * 3.0);
        } else {
            col = mix(accentColor, primaryColor, (colorPhase - 0.666) * 3.0);
        }

        // --------------------------------------------------
        // 부드러운 radial 그라디언트 + 디더링으로 밴딩 제거
        // --------------------------------------------------
        float disNorm = dis / rad;

        // 기본 부드러운 그라디언트 (중심에서 가장자리로 감소)
        float f = 1.0 - disNorm * disNorm;
        f = clamp(f, 0.0, 1.0);

        // 밝은 영역에서 밴딩 줄이기 위한 디더링 노이즈
        // (각 원, 시간에 따라 조금씩 다른 패턴)
        float dither =
            (hash21(fragCoord + vec2(t * 13.17, fi * 7.31)) - 0.5)
            * 0.04; // 너무 세면 노이즈 느낌 나므로 약하게
        // 밝은 영역(하이라이트)에서 더 강하게
        dither *= (0.3 + 0.7 * f);

        f = clamp(f + dither, 0.0, 1.0);

        // softness를 실제로 사용해서 edge 두께 조절
        float baseEdge = 0.0095;
        float edgeWidth = baseEdge + softness * 0.25; // softness에 따라 두꺼워짐
        float edgeInner = rad * edgeWidth;

        float edgeMask = 1.0 - smoothstep(edgeInner, rad, dis);

        float circleAlpha = edgeMask * f * max(circleOpacity, 0.0);

        color += col * circleAlpha;
        totalAlpha += circleAlpha;
    }

    vec3 noiseCol = rand3(fragCoord + vec2(floor(t * 60.0), 0.0));

    vec3 finalRGB = color * 3.0 - noiseCol * 0.05;
    finalRGB *= clamp(overlayAlpha, 0.0, 1.0);

    // (선택) 감마 보정으로 하이라이트 밴딩을 더 줄이고 싶으면 주석 해제
    finalRGB = pow(max(finalRGB, 0.0), vec3(1.0 / 2.2));

    float finalAlpha = clamp(totalAlpha * overlayAlpha * uAlpha, 0.0, 1.0);

return vec4(finalRGB, finalAlpha);

}

