uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float radiusX; // min: 0.0, max: 0.1, default: 0.05 = 화면의 5%)
uniform float radiusY; // min: 0.0, max: 0.1, default: 0.05 = 화면의 5%)
int uSampleCount = 9; //min: 5, max: 25, default: 15, 블러 샘플 개수 (홀수 권장)
float uAlpha = 1.0; //min: 0.0, max: 1.0, default: 1.0, 투명도

vec2 clampUV(vec2 uv) {
   return clamp(uv, 0.0, 1.0);
}

float gaussian(float x, float sigma) {
   return exp(-0.5 * x * x / (sigma * sigma));
}

vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

   // 정규화된 블러 반지름 (화면 크기 비율)
   vec2 normalizedBlurRadius = vec2(radiusX,radiusY);

   // 종횡비 보정 (정사각형이 아닌 경우 원형 블러 유지)
   float aspectRatio = iResolution.x / iResolution.y;
   if(aspectRatio > 1.0) {
       normalizedBlurRadius.x /= aspectRatio;
   } else {
       normalizedBlurRadius.y *= aspectRatio;
   }

   vec4 result = vec4(0.0);
   float totalWeight = 0.0;

   // 가우시안 시그마 값
   float sigma = (radiusX+radiusY)/2.0 * 0.333;

   // 샘플링 범위 계산
   int halfSamples = uSampleCount / 2;

   // 2D 가우시안 블러 적용
   for(int x = 0; x < 25; x++) {
       if(x >= uSampleCount) break;

       for(int y = 0; y < 25; y++) {
           if(y >= uSampleCount) break;

           // 샘플 오프셋 계산 (정규화된 좌표 기준)
           vec2 offset = vec2(
               float(x - halfSamples) / float(halfSamples) * normalizedBlurRadius.x,
               float(y - halfSamples) / float(halfSamples) * normalizedBlurRadius.y
           );

           // 샘플 위치 (CLAMP 모드 적용)
           vec2 sampleUV = clampUV(uv + offset);

           // 가우시안 가중치 계산
           float distance = length(offset / normalizedBlurRadius);
           float weight = gaussian(distance, 1.0);

           // 텍스처 샘플링
           vec4 sampleColor = composable.eval(sampleUV * iResolution.xy);

           result += sampleColor * weight;
           totalWeight += weight;
       }
   }

   // 정규화
   if(totalWeight > 0.0) {
       result /= totalWeight;
   }

return vec4(result.rgb * uAlpha, result.a * uAlpha);

}

